/** True when the recipe still prints one of its bought-product rows. */
export function appwideBought(recipe: Pick<Recipe, "id" | "ingredients">): boolean {
  const rows = APPWIDE_BOUGHT_ROWS[recipe.id];
  return !!rows && recipe.ingredients.some((i) => rows.includes(i.name));
}

